function swapPrefixSuffix(arr) {
  if (arr.length === 0) {
    return;
  }

  const n = arr.length;

  // Reverse the whole array
  let l = 0,
    r = n - 1;
  while (l < r) {
    [arr[l], arr[r]] = [arr[r], arr[l]];
    l++;
    r--;
  }

  // Reverse the last n/3 elements
  l = Math.floor((2 * n) / 3);
  r = n - 1;
  while (l < r) {
    [arr[l], arr[r]] = [arr[r], arr[l]];
    l++;
    r--;
  }

  // Reverse the first 2n/3 elements
  l = 0;
  r = Math.floor((2 * n) / 3) - 1;
  while (l < r) {
    [arr[l], arr[r]] = [arr[r], arr[l]];
    l++;
    r--;
  }
}

