class SwapPrefixSuffix {
  public void solve(char[] arr) {
    if (arr.length == 0) {
      return;
    }

    int n = arr.length;

    // Reverse the whole array
    int l = 0, r = n - 1;
    while (l < r) {
      char temp = arr[l];
      arr[l] = arr[r];
      arr[r] = temp;
      l++;
      r--;
    }

    // Reverse the last n/3 elements
    l = 2 * n / 3;
    r = n - 1;
    while (l < r) {
      char temp = arr[l];
      arr[l] = arr[r];
      arr[r] = temp;
      l++;
      r--;
    }

    // Reverse the first 2n/3 elements
    l = 0;
    r = (2 * n / 3) - 1;
    while (l < r) {
      char temp = arr[l];
      arr[l] = arr[r];
      arr[r] = temp;
      l++;
      r--;
    }
  }
}

